<?php
declare(strict_types=1); require_once __DIR__.'/includes/functions.php'; require_once __DIR__.'/classes/RecipeRepository.php';
$filters=['q'=>$_GET['q']??'','cuisine'=>$_GET['cuisine']??'','category'=>$_GET['category']??'','ingredient'=>$_GET['ingredient']??'','diet'=>$_GET['diet']??'','max_minutes'=>$_GET['max_minutes']??'','sort'=>$_GET['sort']??'popular'];
$repo=new RecipeRepository();$recipes=$repo->search($filters);
$cuisines=db()->query('SELECT DISTINCT cuisine FROM recipes WHERE status="approved" ORDER BY cuisine')->fetchAll(PDO::FETCH_COLUMN);$categories=db()->query('SELECT DISTINCT category FROM recipes WHERE status="approved" ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);$tags=db()->query('SELECT name FROM tags ORDER BY name')->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Discover recipes'; require __DIR__.'/includes/header.php';
?>
<section class="browse-head"><div class="container"><span class="eyebrow">Discover</span><h1>Find a recipe for right now</h1><p>Use ingredients, cuisine, dietary needs, preparation time and community signals to narrow the collection.</p></div></section>
<section class="section container"><form class="filter-panel" method="get"><div class="filter-search"><label>Keyword search<input type="search" name="q" value="<?=e((string)$filters['q'])?>" placeholder="Recipe, dish or keyword"></label><label>Ingredient<input name="ingredient" value="<?=e((string)$filters['ingredient'])?>" placeholder="e.g. chicken"></label></div><div class="filter-grid"><label>Cuisine<select name="cuisine"><option value="">Any cuisine</option><?php foreach($cuisines as $v):?><option <?=($filters['cuisine']===$v?'selected':'')?> value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select></label><label>Category<select name="category"><option value="">Any category</option><?php foreach($categories as $v):?><option <?=($filters['category']===$v?'selected':'')?> value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select></label><label>Dietary tag<select name="diet"><option value="">Any diet</option><?php foreach($tags as $v):?><option <?=($filters['diet']===$v?'selected':'')?> value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select></label><label>Maximum total time<select name="max_minutes"><option value="">Any time</option><?php foreach([15,30,45,60,90] as $v):?><option <?=((int)$filters['max_minutes']===$v?'selected':'')?> value="<?=$v?>">Under <?=$v?> min</option><?php endforeach;?></select></label><label>Sort by<select name="sort"><option value="popular" <?=($filters['sort']==='popular'?'selected':'')?>>Popularity</option><option value="rating" <?=($filters['sort']==='rating'?'selected':'')?>>Highest rating</option><option value="newest" <?=($filters['sort']==='newest'?'selected':'')?>>Newest</option><option value="quickest" <?=($filters['sort']==='quickest'?'selected':'')?>>Quickest</option></select></label><div class="filter-actions"><button class="button button-primary">Apply filters</button><a class="button button-ghost" href="<?=e(url('browse.php'))?>">Clear</a></div></div></form>
<div class="results-bar"><strong><?=count($recipes)?> recipes found</strong><span>Approved community recipes only</span></div><div class="recipe-grid"><?php if(!$recipes):?><div class="empty-state"><h3>No exact matches</h3><p>Try removing one filter or using a broader ingredient.</p></div><?php endif;?><?php foreach($recipes as $recipe) require __DIR__.'/includes/recipe_card.php';?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
